// Congested instances have two useful dispatch-headroom regimes. Lower-price
// horizons benefit from a wider action envelope, while high-price horizons are
// more sensitive to feasibility deflation and use a tighter envelope. Select
// the regime from the complete day-ahead forecast instead of applying one
// network_derating constant to every instance.
fn congested_adaptive_derating(challenge: &Challenge) -> f64 {
    let mut price_sum = 0.0_f64;
    let mut price_count = 0usize;
    for price in challenge.market.day_ahead_prices.iter().flatten() {
        price_sum += *price;
        price_count += 1;
    }
    if price_count == 0 {
        return 0.35;
    }

    let mean_day_ahead_price = price_sum / price_count as f64;
    if mean_day_ahead_price <= 44.0 { 0.48 } else { 0.38 }
}

// Dense horizons split into two stable price regimes. Lower-price horizons
// benefit from concentrating the line-congestion premium more sharply, while
// higher-price horizons need a slightly broader premium to preserve profitable
// dispatch choices. Select the shape from information available in the
// challenge rather than applying one exponent to every instance.
fn dense_adaptive_premium_gamma(challenge: &Challenge) -> f64 {
    let mut price_sum = 0.0_f64;
    let mut price_count = 0usize;
    for price in challenge.market.day_ahead_prices.iter().flatten() {
        price_sum += *price;
        price_count += 1;
    }
    if price_count == 0 {
        return 4.0;
    }

    let mean_day_ahead_price = price_sum / price_count as f64;
    if mean_day_ahead_price <= 44.5 { 5.0 } else { 4.0 }
}

