const LOOKAHEAD: usize = 32;
const FLOW_REPAIR_ITERS: usize = 72;
const FLOW_BISECT_ITERS: usize = 36;
const MIN_ACTION_MW: f64 = 1e-6;

pub fn solve_challenge(
    challenge: &Challenge,
