extern "C" __global__ void initialize_labels(
    int num_nodes,
    int* labels
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= num_nodes) return;

    // Each node starts with its own ID as label
    labels[tid] = tid;
